const hypoglykaemieQuestions: MultipleChoiceQuestion[] = [
  { id: "hypo-q-01", mode: "multiple", prompt: "Welche Aussage bildet die Blutzucker-Richtwerte dieser Lernunterlage korrekt ab?", options: [{ text: "Unter 50 mg/dl (etwa 2,8 mmol/l); Begleitsymptome können bereits bei 60–80 mg/dl auftreten", correct: true }, { text: "Unter 80 mg/dl ist immer eine schwere Hypoglykämie bewiesen" }, { text: "Unter 2,8 mg/dl; Symptome beginnen erst unter 50 mmol/l" }, { text: "Der Messwert ist bedeutungslos, wenn autonome Zeichen fehlen" }], source: "Als Richtwert gilt < 50 mg/dl beziehungsweise etwa 2,8 mmol/l. Beschwerden können individuell bereits bei 60–80 mg/dl beginnen.", difficulty: 1 },
  { id: "hypo-q-02", mode: "multiple", prompt: "Welche Zuordnungen der endokrinen Pankreaszellen sind korrekt?", options: [{ text: "β-Zellen bilden Insulin", correct: true }, { text: "α-Zellen bilden Glukagon", correct: true }, { text: "δ-Zellen bilden Somatostatin", correct: true }, { text: "Azini bilden Insulin und geben es in den Ductus pancreaticus ab" }], source: "In den Langerhans-Inseln bilden β-Zellen Insulin, α-Zellen Glukagon und δ-Zellen Somatostatin.", difficulty: 1 },
  { id: "hypo-q-03", mode: "multiple", prompt: "Welcher Mechanismus erklärt die neurologischen Ausfälle bei ausgeprägter Hypoglykämie am unmittelbarsten?", options: [{ text: "Zerebraler Glukosemangel stört die Energiegewinnung und damit die neuronale Funktion", correct: true }, { text: "Glukagon blockiert die Sauerstoffdiffusion an der Alveole" }, { text: "Insulin verschließt mechanisch die Hirnarterien" }, { text: "Eine Hyperkapnie entleert die Glykogenspeicher der Schädelknochen" }], source: "Das Gehirn ist auf Glukose angewiesen; der Energiemangel führt bis zum Ausfall von Schutzreflexen und zur Zellschädigung.", difficulty: 1 },
  { id: "hypo-q-04", mode: "multiple", prompt: "Welche Befunde gehören typischerweise zu den autonomen Warnzeichen?", options: [{ text: "Schwitzen und Blässe", correct: true }, { text: "Zittern und Heißhunger", correct: true }, { text: "Tachykardie und Unruhe", correct: true }, { text: "Persistierende Hemiplegie als ausschließlich autonomes Zeichen" }], source: "Autonome Zeichen umfassen unter anderem Schwitzen, Blässe, Zittern, Heißhunger, Unruhe und Tachykardie.", difficulty: 1 },
  { id: "hypo-q-05", mode: "multiple", prompt: "Welche Messstrategie ist bei ungeklärter Bewusstseinsstörung korrekt?", options: [{ text: "Blutzucker früh aus kapillärem Blut bestimmen und nach der Intervention erneut messen", correct: true }, { text: "Erst nach Ausschluss eines Schlaganfalls messen" }, { text: "Den Kontrollwert aus der laufenden Infusionsleitung entnehmen" }, { text: "Bei fehlendem Heißhunger auf die Messung verzichten" }], source: "Die frühe kapilläre BZ-Messung gehört zur Beurteilung; Kontrollwerte werden nicht aus einer Flexüle gewonnen.", difficulty: 1 },
  { id: "hypo-q-06", mode: "multiple", prompt: "Welche Konstellationen können bei behandelten Diabetiker:innen eine Hypoglykämie auslösen?", options: [{ text: "Insulindosis ohne passende Nahrungsaufnahme", correct: true }, { text: "Ungewohnte körperliche Belastung", correct: true }, { text: "Alkohol oder Gastroenteritis", correct: true }, { text: "Eine regelrechte Mahlzeit bei unveränderter Therapie schließt jede Hypoglykämie sicher aus" }], source: "Auslöser sind besonders ein Missverhältnis aus Medikament, Nahrung und Verbrauch sowie Alkohol, Erkrankung oder Pumpenproblem.", difficulty: 1 },
  { id: "hypo-q-07", mode: "multiple", prompt: "Ein wacher, kooperativer Erwachsener hat typische Symptome und 42 mg/dl. Welcher Weg entspricht VFA 27?", options: [{ text: "100 ml Glukose 20 % oder eine entsprechende Substitution per os, danach kapilläre Kontrolle", correct: true }, { text: "Orale Gabe wegen Aspirationsgefahr grundsätzlich vermeiden" }, { text: "Sofort 2 ml/kgKG Glukose 20 % intravenös ohne Zugangskontrolle" }, { text: "Erst transportieren und in der Klinik behandeln" }], source: "Bei Wachheit und Kooperation sieht VFA 27 eine orale Gabe von 20 g Glukose und anschließend eine kapilläre Kontrolle vor.", difficulty: 2 },
  { id: "hypo-q-08", mode: "multiple", prompt: "Welche Befunde sprechen für eine neuroglykopenische Beteiligung?", options: [{ text: "Verwirrtheit oder atypisches Verhalten", correct: true }, { text: "Sprach- oder Sehstörung", correct: true }, { text: "Krampfanfall oder Bewusstlosigkeit", correct: true }, { text: "Isolierter Heißhunger ohne neurologische Veränderung" }], source: "Neuroglykopenische Zeichen reichen von kognitiver und fokaler Störung bis zu Krampf und Bewusstlosigkeit.", difficulty: 2 },
  { id: "hypo-q-09", mode: "multiple", prompt: "Nach Glukose normalisiert sich der BZ, die Aphasie bleibt jedoch bestehen. Welche Schlussfolgerung ist am besten begründet?", options: [{ text: "Die Hypoglykämie wurde behandelt; ein Schlaganfall oder eine andere Ursache muss weiterverfolgt werden", correct: true }, { text: "Der Normalwert beweist, dass keine weitere neurologische Diagnostik nötig ist" }, { text: "Persistierende Aphasie ist eine erwartete autonome Reaktion" }, { text: "Die Glukosegabe muss ohne erneute klinische Prüfung beliebig oft wiederholt werden" }], source: "Nach Behandlung erfolgt die Re-Evaluation. Persistierende Defizite verlangen die weitere Suche nach Differenzialdiagnosen.", difficulty: 2 },
  { id: "hypo-q-10", mode: "multiple", prompt: "Welche Punkte müssen vor einer intravenösen Glukosegabe besonders gesichert sein?", options: [{ text: "Sicherer Gefäßzugang mit freiem Lauf", correct: true }, { text: "Absaug- und Atemwegsbereitschaft bei eingeschränkter Vigilanz", correct: true }, { text: "Ausgangswert und klinischer Befund für die Verlaufskontrolle", correct: true }, { text: "Die Glukose darf bevorzugt paravasal gegeben werden, um Venenreizungen zu vermeiden" }], source: "Ein sicherer Zugang schützt vor Gewebsnekrose; zugleich müssen Atemweg, Ausgangsbefund und Verlauf kontrolliert werden.", difficulty: 2 },
  { id: "hypo-q-11", mode: "multiple", prompt: "Welche Kombination trennt Typ-1- und Typ-2-Diabetes korrekt, ohne die akute Hypoglykämie falsch zu erklären?", options: [{ text: "Typ 1: autoimmune β-Zell-Zerstörung und absoluter Insulinmangel; Typ 2: Insulinresistenz plus Sekretionsstörung", correct: true }, { text: "Typ 1: Insulinresistenz; Typ 2: vollständige autoimmune β-Zell-Zerstörung" }, { text: "Beide Typen verursachen Hypoglykämie ausschließlich durch körpereigene Insulinüberproduktion" }, { text: "Der Diabetestyp ersetzt die Prüfung von Medikament, Nahrung und Belastung" }], source: "Typ 1 und Typ 2 unterscheiden sich in der Grunderkrankung; die akute Hypoglykämie wird meist durch ein Therapie-Nahrungs-Verbrauchs-Missverhältnis ausgelöst.", difficulty: 2 },
  { id: "hypo-q-12", mode: "multiple", prompt: "Welche Maßnahmen gehören zur sicheren Verlaufsbeobachtung nach zunächst erfolgreicher Glukosegabe?", options: [{ text: "Wiederholte kapilläre BZ-Kontrolle", correct: true }, { text: "Neurologische und allgemeine klinische Reevaluation", correct: true }, { text: "Ursachensuche sowie Transport- und Überwachungsentscheidung", correct: true }, { text: "Beendigung jeder Beobachtung unmittelbar nach dem ersten Normalwert" }], source: "Glukose wirkt kurz; deshalb müssen BZ, Klinik, Ursache und Transportfähigkeit weiter beurteilt werden.", difficulty: 2 },
  { id: "hypo-q-13", mode: "multiple", prompt: "Eine bewusstlose erwachsene Patientin hat 31 mg/dl und einen sicher laufenden i.v. Zugang. Was sieht VFA 27 zunächst vor?", options: [{ text: "100 ml Glukose 20 % (= 20 g) langsam intravenös, danach kapilläre Kontrolle", correct: true }, { text: "100 ml Glukose 40 % als Bolus ohne Kontrolle" }, { text: "Orale Glukose trotz fehlender Schutzreflexe" }, { text: "2 ml/kgKG Glukose 20 % nach dem Kinderalgorithmus" }], source: "Bei fehlender Wachheit werden 100 ml Glukose 20 % langsam intravenös über einen sicheren Zugang gegeben und anschließend kontrolliert.", difficulty: 3 },
  { id: "hypo-q-14", mode: "multiple", prompt: "Trotz initialer Behandlung bessert sich die Bewusstseinslage nicht. Welche Schritte sind gleichzeitig begründet?", options: [{ text: "Kapillären BZ erneut kontrollieren", correct: true }, { text: "Nach VFA eine einmalige weitere intravenöse Gabe prüfen", correct: true }, { text: "Apoplex, Trauma, Intoxikation, Infekt und Krampfanfall weiter abklären", correct: true }, { text: "Monitoring und Transport bis zur vollständigen Diagnose am Einsatzort aussetzen" }], source: "VFA 27 verbindet die einmalige Wiederholung bei fehlender Besserung mit der Suche nach anderen Ursachen, Überwachung und Transport.", difficulty: 3 },
  { id: "hypo-q-15", mode: "multiple", prompt: "Warum kann eine Glukosegabe trotz klinischer Besserung einen erneuten Abfall nicht verhindern?", options: [{ text: "Glukose wird direkt verwertet und wirkt kurz; die fortbestehende Ursache kann den BZ erneut senken", correct: true }, { text: "Intravenöse Glukose wird grundsätzlich nicht metabolisiert" }, { text: "Insulin wird durch Glukose dauerhaft neutralisiert" }, { text: "Ein erster Normalwert beendet jede Wirkung blutzuckersenkender Medikamente" }], source: "Die Wirkung ist kurz; ohne Beseitigung der Ursache kann der Blutzucker erneut abfallen.", difficulty: 3 },
  { id: "hypo-q-16", mode: "multiple", prompt: "Welche Risiken müssen bei einer schweren Hypoglykämie mit Krampfanfall aktiv mitgedacht werden?", options: [{ text: "Aspiration und Verlust der Schutzreflexe", correct: true }, { text: "Trauma und Hypothermie", correct: true }, { text: "Rhythmusstörung bis Herz-Kreislauf-Stillstand", correct: true }, { text: "Sicherer Ausschluss einer Intoxikation durch den niedrigen BZ" }], source: "Krampf, Aspiration, Verletzung, Hypothermie, Rhythmusstörung und Kreislaufstillstand gehören zu den vitalen Gefahren.", difficulty: 3 },
  { id: "hypo-q-17", mode: "multiple", prompt: "Ein 38-kg-Kind ist nicht wach und hat 2,7 mmol/l. Welche Anfangsdosis zeigt VFA 28?", options: [{ text: "2 ml/kgKG Glukose 20 % langsam intravenös", correct: true }, { text: "100 ml Glukose 20 % unabhängig vom Gewicht" }, { text: "1 ml/kgKG Glukose 20 % als erste Dosis" }, { text: "Orale Gabe trotz fehlender Wachheit" }], source: "VFA 28 sieht bei Kindern unter 50 kg initial 2 ml/kgKG Glukose 20 % i.v. vor; bei fehlender Besserung folgt 1 ml/kgKG.", difficulty: 3 },
  { id: "hypo-q-18", mode: "multiple", prompt: "Welche Dokumentation ermöglicht eine fachlich belastbare Übergabe nach schwerer Hypoglykämie?", options: [{ text: "Ausgangswert, Messort und klinischer Ausgangsbefund", correct: true }, { text: "Applikationsweg, Menge, Zeitpunkt und sichere Zugangslage", correct: true }, { text: "Kontrollwerte, neurologischer Verlauf, vermutete Ursache und Begleitmedikation", correct: true }, { text: "Nur der letzte Normalwert ohne Angaben zum Verlauf" }], source: "Die Übergabe braucht Ausgangsbefund, Intervention, Kontrollwerte, Wirkung, vermutete Ursache und Verlauf.", difficulty: 3 },
];

const hodentorsionQuestions: MultipleChoiceQuestion[] = [
  { id: "hoden-q-01", mode: "multiple", prompt: "Welche Aussagen beschreiben die Hodentorsion korrekt?", options: [{ text: "Hoden und Samenstrang können sich teilweise oder vollständig um die eigene Achse drehen", correct: true }, { text: "Die Gefäßbeeinträchtigung kann über eine Ischämie in eine irreversible Nekrose übergehen", correct: true }, { text: "Es handelt sich primär um eine bakterielle Entzündung des Nebenhodens" }, { text: "Ein unauffälliger Urinstatus schließt die Diagnose mit hoher Sicherheit aus" }], source: "Die Hodentorsion ist die axiale Drehung von Hoden und Samenstrang mit Durchblutungsstörung bis zur Nekrose; Labor und Urin sind häufig nicht wegweisend.", difficulty: 1 },
  { id: "hoden-q-02", mode: "multiple", prompt: "Welche Strukturen und Funktionen sind für das Verständnis der Hodentorsion wesentlich?", options: [{ text: "Der Samenstrang enthält unter anderem Samenleiter, Blutgefäße und Nerven", correct: true }, { text: "Der Nebenhoden dient Reifung und Speicherung der Spermien", correct: true }, { text: "Der Hoden bildet Spermien und Testosteron", correct: true }, { text: "Der Musculus cremaster bildet die Spermien und gibt sie direkt in die Harnröhre ab" }], source: "Hoden, Nebenhoden, Samenleiter und die im Samenstrang verlaufenden Gefäße erklären Funktion und Schädigungsmechanismus.", difficulty: 1 },
  { id: "hoden-q-03", mode: "multiple", prompt: "Welche Stationen gehören zur typischen vaskulären Schädigungskaskade?", options: [{ text: "Venöse Abflussbehinderung mit Stauung und Schwellung", correct: true }, { text: "Nachfolgende Einschränkung der arteriellen Versorgung", correct: true }, { text: "Ischämie mit möglicher irreversibler Nekrose", correct: true }, { text: "Primär gesteigerter arterieller Zustrom mit dauerhafter Hyperperfusion" }], source: "Die Rotation behindert zunächst den venösen Rückstrom; Schwellung und Druck beeinträchtigen anschließend den arteriellen Zufluss.", difficulty: 1 },
  { id: "hoden-q-04", mode: "multiple", prompt: "Welche Konstellationen passen zu Auftreten und Auslösern einer Hodentorsion?", options: [{ text: "Plötzlicher Beginn im Schlaf ohne erinnerliches Trauma", correct: true }, { text: "Beginn bei Sport oder nach äußerem Reiz mit kräftiger Cremasterreaktion", correct: true }, { text: "Häufigkeit im Säuglingsalter sowie in Pubertät und jungem Erwachsenenalter", correct: true }, { text: "Ausschließlich Patienten über 65 Jahre nach Harnwegsinfekt" }], source: "Die Torsion kann idiopathisch im Schlaf, bei Sport, Trauma oder erotischer Aktivität auftreten; typische Altersgipfel liegen früh im Leben.", difficulty: 1 },
  { id: "hoden-q-05", mode: "multiple", prompt: "Welche Befunde stützen bei akutem Skrotalschmerz die Arbeitsdiagnose Hodentorsion?", options: [{ text: "Plötzlicher starker einseitiger Schmerz mit Übelkeit oder Erbrechen", correct: true }, { text: "Hochstand und deutlicher Seitenunterschied des betroffenen Hodens", correct: true }, { text: "Schwellung, Spannung und ausgeprägte Druckempfindlichkeit", correct: true }, { text: "Schmerzfreiheit bei jeder Bewegung als typischer Leitsymptombefund" }], source: "Akuter Schmerz, Hochstand, Schwellung und vegetative Begleitzeichen bilden die typische klinische Konstellation.", difficulty: 1 },
  { id: "hoden-q-06", mode: "multiple", prompt: "Welche Aussagen zu Ger-, Brunzel- und Prehn-Zeichen sind richtig?", options: [{ text: "Das Brunzel-Zeichen bezeichnet den Hochstand des betroffenen Hodens", correct: true }, { text: "Das Ger-Zeichen beschreibt eine Einziehung beziehungsweise Verkürzung der Skrotalhaut", correct: true }, { text: "Eine Schmerzverstärkung beim vorsichtigen Anheben kann als positives Prehn-Zeichen gewertet werden", correct: true }, { text: "Ein negatives Prehn-Zeichen schließt eine Hodentorsion sicher aus" }], source: "Die Zeichen können den Verdacht stützen, sind aber einzeln nicht ausreichend zum sicheren Ausschluss.", difficulty: 1 },
  { id: "hoden-q-07", mode: "multiple", prompt: "Ein 16-Jähriger klagt nur über plötzlich einsetzenden Unterbauch- und Leistenschmerz mit Erbrechen. Welche Konsequenzen sind begründet?", options: [{ text: "Die Genitalregion diskret in die fokussierte Untersuchung einbeziehen", correct: true }, { text: "Eine Hodentorsion trotz fehlender spontaner Angabe von Hodenschmerz mitdenken", correct: true }, { text: "Beginn und frühere selbstlimitierte Episoden exakt erfragen", correct: true }, { text: "Eine urologische Ursache erst nach unauffälligem Abdomen-CT erwägen" }], source: "Eine Hodentorsion kann sich als Unterbauch- oder Leistenschmerz präsentieren; die Zeitachse und urologische Untersuchung bleiben entscheidend.", difficulty: 2 },
  { id: "hoden-q-08", mode: "multiple", prompt: "Welche Anamnesepunkte beeinflussen die präklinische Entscheidung besonders?", options: [{ text: "Exakter Symptombeginn und Verlauf", correct: true }, { text: "Frühere gleichartige Episoden und urologische Vorgeschichte", correct: true }, { text: "Letzte Nahrungsaufnahme wegen möglicher sofortiger Operation", correct: true }, { text: "Erstmalige Schulnote in Biologie ohne Bezug zum Ereignis" }], source: "Zeitpunkt, Verlauf, Rezidive, Vorgeschichte, Auslöser und Nüchternheit sind für Verdacht, Dringlichkeit und Klinikübergabe relevant.", difficulty: 2 },
  { id: "hoden-q-09", mode: "multiple", prompt: "Welche Aussagen zur klinischen Diagnostik und Sonografie treffen zu?", options: [{ text: "Die Duplexsonografie wird im Seitenvergleich beurteilt", correct: true }, { text: "Fehlende oder verminderte Perfusion kann die Torsion stützen", correct: true }, { text: "Ein Whirlpool-Zeichen kann einen verdrehten Samenstrang darstellen", correct: true }, { text: "Nachweisbare arterielle Restperfusion schließt eine partielle Torsion sicher aus" }], source: "Seitenvergleich, Perfusion und Whirlpool-Zeichen sind hilfreich; bei früher oder partieller Torsion kann Restperfusion bestehen.", difficulty: 2 },
  { id: "hoden-q-10", mode: "multiple", prompt: "Welche Differenzialdiagnosen müssen beim akuten Skrotum beziehungsweise ausstrahlenden Leistenschmerz berücksichtigt werden?", options: [{ text: "Hydatidentorsion", correct: true }, { text: "Epididymitis oder Orchitis", correct: true }, { text: "Trauma oder Nierenkolik", correct: true }, { text: "Eine unkomplizierte Myopie als typische Ursache des akuten Skrotums" }], source: "Hydatidentorsion, Entzündungen, Trauma, akutes Abdomen und Nierenkolik gehören zu den relevanten Differenzialdiagnosen.", difficulty: 2 },
  { id: "hoden-q-11", mode: "multiple", prompt: "Welche präklinischen Maßnahmen laufen bei relevantem Torsionsverdacht sinnvoll parallel?", options: [{ text: "cABCDE, Monitoring und symptomorientierte Stabilisierung", correct: true }, { text: "OPQRST/SAMPLERS und schonender lokaler Befund im Seitenvergleich", correct: true }, { text: "Analgesie und frühzeitige Anmeldung in einer Klinik mit Urologie und OP-Möglichkeit", correct: true }, { text: "Abwarten auf eine spontane Schmerzfreiheit vor Beginn der Transportplanung" }], source: "Strukturierte Erstversorgung, fokussierte Anamnese, Analgesie und zeitkritische Transportorganisation erfolgen parallel.", difficulty: 2 },
  { id: "hoden-q-12", mode: "multiple", prompt: "Welche Aussagen zur Bedeutung des 4–6-Stunden-Fensters sind fachlich richtig?", options: [{ text: "Mit zunehmender Ischämiedauer sinkt die Wahrscheinlichkeit des Hodenerhalts", correct: true }, { text: "Vermeidbare Diagnostik- und Transportverzögerungen sind zu reduzieren", correct: true }, { text: "Ein klinisch relevanter Verdacht rechtfertigt die dringliche urologische Vorstellung", correct: true }, { text: "Vor Ablauf von sechs Stunden besteht grundsätzlich kein Risiko einer Gewebeschädigung" }], source: "Vier bis sechs Stunden sind ein kritisches Orientierungsfenster, keine garantierte schadensfreie Frist.", difficulty: 2 },
  { id: "hoden-q-13", mode: "multiple", prompt: "Welche Grundsätze gelten bei starken Schmerzen und gleichzeitigem Verdacht auf Hodentorsion?", options: [{ text: "cABCDE und OPQRST werden strukturiert durchgeführt", correct: true }, { text: "Die Analgesie wird in die zeitkritische Transportorganisation integriert", correct: true }, { text: "Kontinuierliches Monitoring und Transport werden auch nach Schmerzlinderung fortgeführt", correct: true }, { text: "Die definitive urologische Versorgung darf bis zur vollständigen Schmerzfreiheit zurückgestellt werden" }], source: "Schmerztherapie, Überwachung und zeitkritischer Transport laufen parallel; eine Symptomverbesserung hebt die Dringlichkeit nicht auf.", difficulty: 3 },
  { id: "hoden-q-14", mode: "multiple", prompt: "Welche Aussagen folgen für eine Hodentorsion nach direktem Trauma mit NRS 9 aus der VFA-Systematik?", options: [{ text: "Die traumatische Ursache führt in VFA 35 in den traumatischen Schmerzpfad", correct: true }, { text: "Morphin nach VFA 38 kann entsprechend Indikation und Kontraindikationen relevant sein", correct: true }, { text: "Analgesie ersetzt weder urologische Voranmeldung noch zeitkritischen Transport", correct: true }, { text: "Eine Schmerzreduktion beweist, dass keine Torsion mehr besteht" }], source: "Bei traumatischer Ursache gilt der entsprechende Schmerzpfad; Symptomkontrolle ändert die urologische Zeitkritik nicht.", difficulty: 3 },
  { id: "hoden-q-15", mode: "multiple", prompt: "Welche Indikationen führt VFA 36 für Esketamin bei Erwachsenen auf?", options: [{ text: "Traumabedingter Schmerz", correct: true }, { text: "Transthorakale Schrittmachertherapie", correct: true }, { text: "Notfallkardioversion", correct: true }, { text: "Jeder atraumatische Skrotalschmerz unabhängig von der Ursache" }], source: "VFA 36 nennt traumabedingten Schmerz, transthorakale Schrittmachertherapie und Notfallkardioversion als Indikationen.", difficulty: 3 },
  { id: "hoden-q-16", mode: "multiple", prompt: "Welche Sicherheits- und Kontrollschritte gehören nach VFA 36 zur Esketaminanalgesie?", options: [{ text: "Angepasste Sauerstoffgabe mit Ziel SpO₂ über 90 % und Beatmungsbereitschaft", correct: true }, { text: "EKG- und Blutdrucküberwachung", correct: true }, { text: "NRS-Kontrolle und Pflichtdokumentation nach den vorgegebenen Zeitintervallen", correct: true }, { text: "Verzicht auf Monitoring, sobald der Schmerz innerhalb von fünf Minuten sinkt" }], source: "VFA 36 verbindet Esketamin mit O₂-Anpassung, Beatmungsbereitschaft, EKG, RR, serieller NRS-Dokumentation, Monitoring und Transport.", difficulty: 3 },
  { id: "hoden-q-17", mode: "multiple", prompt: "Der Schmerz lässt während des Transports plötzlich deutlich nach. Welche Bewertungen bleiben richtig?", options: [{ text: "Eine spontane Detorsion ist möglich, beseitigt aber den Abklärungsbedarf nicht", correct: true }, { text: "Intermittierende Torsion mit erneuter Verdrehung bleibt möglich", correct: true }, { text: "Zeitpunkt und klinische Veränderung müssen dokumentiert und übergeben werden", correct: true }, { text: "Die Zielklinik kann wegen der Besserung ohne Rücksprache auf eine allgemeine Hausarztpraxis geändert werden" }], source: "Schmerzabnahme schließt die Torsion nicht sicher aus; Rezidiv oder Resttorsion bleiben möglich und verlangen urologische Abklärung.", difficulty: 3 },
  { id: "hoden-q-18", mode: "multiple", prompt: "Welche Übergabe zeigt bei vermuteter Hodentorsion die höchste fachliche Qualität?", options: [{ text: "Exakter Beginn, Verlauf, Seite, Ausstrahlung und Schmerzstärke", correct: true }, { text: "Inspektions- und Tastbefund einschließlich Hochstand und Seitenunterschied", correct: true }, { text: "Vegetative Zeichen, Vorereignisse, letzte Nahrungsaufnahme, Analgesie und Wirkung", correct: true }, { text: "Nur die Vermutung ‚akutes Skrotum‘ ohne Zeitangabe, Befunde oder Maßnahmen" }], source: "Die operative Zeitentscheidung braucht eine präzise Zeitachse, fokussierte Befunde, relevante Anamnese und den dokumentierten Maßnahmenverlauf.", difficulty: 3 },
];

