function multipleChoiceQuestions(questionBank: MultipleChoiceQuestion[]) {
  return questionBank.map((question, questionIndex) => {
    const correctOptions = question.options.filter((option) => option.correct);
    if (correctOptions.length > 1) return { ...question, mode: "multiple" as const };

    const additionalCorrect = additionalCorrectAnswers[question.id];
    const originalCorrect = correctOptions[0];
    const distractors = question.options.filter((option) => !option.correct);
    const replacedDistractor = [...distractors].sort((left, right) => Math.abs(right.text.length - originalCorrect.text.length) - Math.abs(left.text.length - originalCorrect.text.length))[0];
    const retainedDistractors = distractors.filter((option) => option !== replacedDistractor);
    const longestRetained = [...retainedDistractors].sort((left, right) => right.text.length - left.text.length)[0];
    const longestCorrectLength = Math.max(originalCorrect.text.length, additionalCorrect.length);

    const options = question.options.map((option) => {
      if (option === replacedDistractor) return { text: additionalCorrect, correct: true };
      if (questionIndex % 2 === 0 && option === longestRetained && option.text.length <= longestCorrectLength) {
        const otherDistractor = retainedDistractors.find((candidate) => candidate !== option);
        return { text: `${option.text}; ${otherDistractor?.text.charAt(0).toLowerCase()}${otherDistractor?.text.slice(1)}` };
      }
      return option;
    });

    const focus = question.prompt.replace(/\?$/, "");
    return {
      ...question,
      prompt: `Zum Prüfungsaspekt „${focus}“: Welche Aussagen sind richtig?`,
      source: `${question.source} Zusätzlich richtig: ${additionalCorrect}`,
      mode: "multiple" as const,
      options,
    };
  });
}

function shuffledQuestions(questionBank: MultipleChoiceQuestion[], previous: MultipleChoiceQuestion[] = []) {
  const multipleBank = multipleChoiceQuestions(questionBank);
  const next = ([1, 2, 3] as const).flatMap((difficulty) => {
    const tier = multipleBank.filter((question) => question.difficulty === difficulty).map((question) => {
      const options = [...question.options];
      for (let index = options.length - 1; index > 0; index -= 1) {
        const swapIndex = Math.floor(Math.random() * (index + 1));
        [options[index], options[swapIndex]] = [options[swapIndex], options[index]];
      }
      return { ...question, options };
    });
    for (let index = tier.length - 1; index > 0; index -= 1) {
      const swapIndex = Math.floor(Math.random() * (index + 1));
      [tier[index], tier[swapIndex]] = [tier[swapIndex], tier[index]];
    }
    return tier;
  });
  if (previous.length === next.length && previous.every((question, index) => question.id === next[index].id)) next.push(next.shift()!);
  return next;
}

function MultipleChoiceQuiz({ questionBank, condition, onProgressChange, standalone = false }: { questionBank: MultipleChoiceQuestion[]; condition: string; onProgressChange: (progress: QuestionProgress) => void; standalone?: boolean }) {
  const [questions, setQuestions] = useState<MultipleChoiceQuestion[]>([]);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [selected, setSelected] = useState<number[]>([]);
  const [answered, setAnswered] = useState(false);
  const [correctAnswers, setCorrectAnswers] = useState(0);
  const [finished, setFinished] = useState(false);

  const start = () => {
    setQuestions((current) => shuffledQuestions(questionBank, current));
    setQuestionIndex(0);
    setSelected([]);
    setAnswered(false);
    setCorrectAnswers(0);
    setFinished(false);
  };

  const evaluate = (selection: number[]) => {
    const question = questions[questionIndex];
    const correct = question.options.map((option, index) => option.correct ? index : -1).filter((index) => index >= 0);
    const isCorrect = selection.length === correct.length && selection.every((index) => correct.includes(index));
    setSelected(selection);
    setAnswered(true);
    if (isCorrect) setCorrectAnswers((current) => current + 1);
    onProgressChange(recordQuestionAnswer(question.id, isCorrect));
  };

  const answer = (optionIndex: number) => {
    if (answered) return;
    setSelected((current) => current.includes(optionIndex) ? current.filter((index) => index !== optionIndex) : [...current, optionIndex]);
  };

  const next = () => {
    if (questionIndex === questions.length - 1) setFinished(true);
    else {
      setQuestionIndex((current) => current + 1);
      setSelected([]);
      setAnswered(false);
    }
  };

  if (!questions.length) return <div className={`ai-question-panel quiz-launch ${standalone ? "standalone" : ""}`}><div><span className="eyebrow">{standalone ? "MC-Training" : "Nach dem Lesen"}</span><h2>Schwere Multiple-Choice-Fragen</h2><p>Jede Aufgabe zu {condition} enthält mehrere richtige Antworten. Die Aufgaben prüfen medizinische Zusammenhänge und passende Thüringer VFA; Fragen und Antworten werden bei jedem Neustart neu gemischt.</p></div><button className="primary-button" onClick={start}>{standalone ? "Training starten" : "Prüfungsfragen starten"}</button></div>;

  if (finished) return <section className={`chapter-quiz quiz-result ${standalone ? "standalone" : ""}`}><span className="eyebrow">Training abgeschlossen</span><h2>{correctAnswers} von {questions.length} richtig</h2><p>Jede Antwort wurde in deiner Fortschrittsstatistik gespeichert. Falsche Antworten setzen die jeweilige Frage wieder auf 0 %.</p><button className="primary-button" onClick={start}>Neu starten und mischen</button></section>;

  const question = questions[questionIndex];
  const correctIndices = question.options.map((option, index) => option.correct ? index : -1).filter((index) => index >= 0);
  const wasCorrect = answered && selected.length === correctIndices.length && selected.every((index) => correctIndices.includes(index));
  const difficultyLabel = question.difficulty === 1 ? "Grundlage" : question.difficulty === 2 ? "Vertiefung" : "Staatsexamensniveau";
  return <section className={`chapter-quiz ${standalone ? "standalone" : ""}`}><div className="chapter-quiz-head"><div><span className="choice-type-badge multiple">Multiple Choice · Mehrere Antworten sind richtig</span><small>Frage {questionIndex + 1} von {questions.length} · {difficultyLabel}</small></div><div className="quiz-mini-progress"><span style={{ width: `${((questionIndex + (answered ? 1 : 0)) / questions.length) * 100}%` }} /></div></div><h2>{question.prompt}</h2><div className="multiple-choice-actions">{question.options.map((option, optionIndex) => { const chosen = selected.includes(optionIndex); const answerClass = answered ? option.correct ? "correct" : chosen ? "wrong" : "dimmed" : chosen ? "selected" : ""; return <button key={option.text} className={answerClass} onClick={() => answer(optionIndex)} disabled={answered} aria-pressed={chosen}><span>{String.fromCharCode(65 + optionIndex)}</span><b>{option.text}</b></button>; })}</div>{!answered && <button className="check-multiple-answer" onClick={() => evaluate(selected)} disabled={!selected.length}>Auswahl prüfen</button>}{answered && <div className={`quiz-source-answer ${wasCorrect ? "correct" : "wrong"}`}><b>{wasCorrect ? "Richtig beantwortet" : "Falsch beantwortet"}</b><p>{question.source}</p><button onClick={next}>{questionIndex === questions.length - 1 ? "Ergebnis anzeigen" : "Nächste Frage"} →</button></div>}</section>;
}

